#!/usr/bin/env python3
"""Build the dependency-free static learning site. Run: python3 build.py."""
from pathlib import Path
from html import escape
import json
import re
import sys

ROOT = Path(__file__).resolve().parent
sys.path.insert(0, str(ROOT / "content"))
from foundations import MODULES, RESOURCES
from labs import LABS
from weeks import WEEKS
from research import PROJECT_SECTIONS, PAPERS
from interviews import QUESTIONS, CAREER_PHASES, CODING_PRACTICE

E = lambda x: escape(str(x), quote=True)
NAV = [("index.html","Overview","00"),("roadmap.html","Weekly roadmap","01"),("theory.html","Theory & foundations","02"),("implementation.html","Implementation labs","03"),("research.html","Research project","04"),("reading.html","Reading room","05"),("interviews.html","Interview preparation","06"),("resources.html","Resource library","07")]
CHECKS = [f"week-{w['n']}-output-{i}" for w in WEEKS for i in range(len(w['outputs']))] + [f"module-{m['id']}" for m in MODULES] + [f"lab-{l['id']}" for l in LABS] + [f"release-{i}" for i in range(6)]
SEARCH = []
LAB_BY_ID = {x["id"]: x for x in LABS}

def ul(items): return '<ul>'+''.join(f'<li>{E(x)}</li>' for x in items)+'</ul>'
def ol(items): return '<ol>'+''.join(f'<li>{E(x)}</li>' for x in items)+'</ol>'
def refs(keys):
    return '<div class="resource-links">'+''.join(f'<a class="resource-link" href="{E(RESOURCES[k][1])}" target="_blank" rel="noopener">{E(RESOURCES[k][0])}</a>' for k in keys)+'</div>'
def check(id, text): return f'<label class="check"><input type="checkbox" data-check="{E(id)}"><span>{E(text)}</span></label>'
def tinycheck(id): return f'<label class="tiny-check"><input type="checkbox" data-check="{E(id)}">Completed</label>'
def heading(kicker,title,description): return f'<div class="page-heading"><div class="eyebrow">{E(kicker)}</div><h1>{E(title)}</h1><p class="lead">{E(description)}</p></div>'
def section(id,title,body): return f'<section id="{E(id)}"><h2>{E(title)}</h2>{body}</section>'
def toc(items): return '<aside class="toc" aria-label="On this page"><h3>On this page</h3>'+''.join(f'<a href="#{E(id)}">{E(title)}</a>' for id,title in items)+'</aside>'
def article(sections): return '<div class="article-layout"><article class="article">'+''.join(section(*s) for s in sections)+'</article>'+toc([(s[0],s[1]) for s in sections])+'</div>'
def hours(w):
    labels=['Theory','Coding labs','Research','Interview / career']
    bar='<div class="hours-bar" aria-hidden="true">'+''.join(f'<span style="width:{h/42*100:.3f}%"></span>' for h in w['hours'])+'</div>'
    legend='<div class="hours-legend">'+''.join(f'<span><b>{h} h</b> {label}</span>' for h,label in zip(w['hours'],labels))+'</div>'
    return bar+legend
def weekcard(w):
    n=w['n']
    return f'<div class="card week-card" data-category="{E(w["phase"])}"><div class="card-top"><span class="card-number">WEEK {n:02}</span><span class="tag{(" orange" if n==7 else "")}">{E(w["phase"])}</span></div><h3><a href="week-{n:02}.html">{E(w["title"])}</a></h3><div class="week-date" data-week-date="{n}"></div><p style="margin-top:12px">{E(w["aim"])}</p>{hours(w)}<div class="card-footer"><span>6 days · 42 hours</span><a href="week-{n:02}.html">Open week →</a></div></div>'
def write(name,title,body,active,kind="Guide",description=""):
    navigation=''
    for file,label,number in NAV:
        aria=' aria-current="page"' if file==active else ''
        selected=' active' if file==active else ''
        navigation+=f'<a class="nav-link{selected}" href="{file}"{aria}><b>{number}</b>{label}</a>'
    text=re.sub('<[^>]+>',' ',body);text=re.sub(r'\s+',' ',text).strip()
    SEARCH.append(dict(title=title,kind=kind,href=name,text=description or text[:450]))
    doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{E(description or 'A detailed 12-week Physical AI study, implementation and research program.')}"/><meta name="theme-color" content="#1b302c"><title>{E(title)} · Fieldwork / Physical AI</title><link rel="stylesheet" href="assets/style.css"><script src="assets/search-index.js" defer></script><script src="assets/app.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><aside class="sidebar" aria-label="Main navigation"><a class="brand" href="index.html"><span class="brand-mark">f.</span><span><span class="brand-name">FIELDWORK</span><span class="brand-sub">THE PHYSICAL AI PROGRAM</span></span></a><button class="search-trigger" data-search>Find a topic <kbd>⌘ K</kbd></button><div class="nav-label">Your workspace</div><nav>{navigation}</nav><div class="side-progress"><div class="progress-head"><span>Program progress</span><strong data-progress-text>0 / {len(CHECKS)}</strong></div><div class="progress-track"><div class="progress-fill" data-progress-fill></div></div><p class="side-note">Saved in this browser. Export to back up or move devices.</p></div><div class="side-bottom"><button class="small-btn" data-export>Export progress</button><button class="small-btn" data-import>Import</button><button class="small-btn" data-print>Print</button></div></aside>
<div class="workspace"><header class="topbar"><button class="mobile-menu" aria-label="Toggle navigation" aria-expanded="false">☰</button><span><span class="dot"></span>STUDY → IMPLEMENT → INVESTIGATE</span><span class="date">12 weeks · 6–8 h/day</span></header><main id="main" class="content">{body}<footer class="footer"><span>Fieldwork / Physical AI · Plan & source review: October 14, 2026</span><span>Original curriculum · Progress stays in your browser · <a href="README.md">About this site</a></span></footer></main></div>
<dialog id="searchDialog" aria-label="Search the program"><div class="search-head"><input id="searchQuery" type="search" aria-label="Search topics, labs and weeks" placeholder="Search PPO, world models, obstacles…"><button data-close-search>Close</button></div><div class="search-results" id="searchResults"></div></dialog><input type="file" id="importFile" accept="application/json" hidden></body></html>'''
    (ROOT/name).write_text(doc,encoding='utf-8')

def build_overview():
    art='''<svg viewBox="0 0 410 280" role="img" aria-label="A robot encounters a blocker, practices in its model, and returns to execution"><defs><pattern id="grid" width="24" height="24" patternUnits="userSpaceOnUse"><path d="M24 0H0V24" fill="none" stroke="#577461" stroke-width=".5" opacity=".35"/></pattern><marker id="arrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#bad59d" stroke-width="1.2"/></marker></defs><rect x="6" y="8" width="394" height="266" rx="12" fill="url(#grid)"/><text x="26" y="35" fill="#b9cbb7" font-family="monospace" font-size="9" letter-spacing="2">THE RECOVERY LOOP</text><path d="M30 223H375" stroke="#69816e"/><path d="M51 220V203L84 146L131 183L164 148" stroke="#dae8cf" stroke-width="12" fill="none" stroke-linejoin="round"/><circle cx="84" cy="146" r="10" fill="#1b302c" stroke="#d6e9c4" stroke-width="3"/><circle cx="131" cy="183" r="8" fill="#1b302c" stroke="#d6e9c4" stroke-width="3"/><path d="M164 148l12-6m-12 6l5 13" stroke="#d6e9c4" stroke-width="4"/><rect x="183" y="177" width="30" height="44" rx="3" fill="#ec7951"/><rect x="245" y="199" width="23" height="22" rx="3" fill="#d9efb3"/><path d="M170 180C178 152 200 150 223 166C246 183 267 183 286 198" stroke="#bad59d" stroke-width="1.5" stroke-dasharray="4 4" fill="none" marker-end="url(#arrow)"/><rect x="208" y="54" width="161" height="83" rx="9" fill="#304a3c" stroke="#71866d" stroke-dasharray="3 4"/><text x="226" y="77" fill="#d9efb3" font-size="9" font-family="monospace" letter-spacing="1">LEARNED WORLD MODEL</text><path d="M232 110L253 96L274 111L304 90L343 106" fill="none" stroke="#d9efb3" stroke-width="2"/><path d="M126 122C139 80 160 81 196 87" fill="none" stroke="#bad59d" marker-end="url(#arrow)"/><path d="M327 149C335 177 336 191 321 211" fill="none" stroke="#bad59d" marker-end="url(#arrow)"/><text x="29" y="251" fill="#b9cbb7" font-family="monospace" font-size="9">OBSERVE</text><text x="156" y="251" fill="#b9cbb7" font-family="monospace" font-size="9">ADAPT</text><text x="283" y="251" fill="#b9cbb7" font-family="monospace" font-size="9">VERIFY</text></svg>'''
    body=f'''<div class="eyebrow">An intentional transition · a tangible research result</div><div class="hero"><div class="hero-copy"><div class="eyebrow">Your next three months</div><h1>Learn the foundations.<br>Build the evidence.</h1><p>A practical program in robot learning, world models and honest self-improvement. Deep theory, working implementations and one focused research artifact.</p><a class="button light" href="roadmap.html" data-current-week-link>Open week 1 →</a><div class="hero-meta"><span>12 focused weeks</span><span>42 core hours / week</span><span>Outreach in week 7</span></div></div><div class="hero-art">{art}</div></div>
    <div class="metric-grid"><div class="metric"><div class="num">12</div><div class="label">Weekly plans, with daily actions</div></div><div class="metric"><div class="num">9</div><div class="label">Theory modules to understand deeply</div></div><div class="metric"><div class="num">12</div><div class="label">Implementation labs & clear checks</div></div><div class="metric"><div class="num">01</div><div class="label">Focused research project</div></div></div>
    <div class="grid-2"><section class="card"><div class="card-label">The research thread</div><h2>Dream. Adapt. Verify.</h2><p>When an unseen obstruction defeats a robot policy, can imagined practice produce a recovery that works physically—with a small, actively chosen budget of real trials?</p><div class="route-mini"><span>Blocked action</span><b>→</b><span>Imagined updates</span><b>→</b><span>Real verification</span></div><a href="research.html">Explore the full protocol →</a></section>
    <section class="card"><div class="card-label">A sustainable seven-hour day</div><div class="session-block"><span class="time">2.5–3 h</span><p><strong>Understand.</strong> Theory, derivations and careful reading.</p></div><div class="session-block"><span class="time">3–3.5 h</span><p><strong>Build.</strong> Coding labs and the research pipeline.</p></div><div class="session-block"><span class="time">0.5–1 h</span><p><strong>Explain.</strong> Retrieval practice, interview coding and private rehearsal.</p></div><p class="small" style="margin-top:15px">These are starting-day proportions. Weekly budgets shift toward research and interviews. Outreach starts only after six full weeks.</p></section></div>
    <div class="section-head"><h2>One program. Three phases.</h2><a href="roadmap.html">See all 12 weeks →</a></div><div class="phase-line"><div class="phase-cell"><div class="label">01 / Weeks 1–4</div><h3>Establish competence</h3><p>Close robotics/RL gaps; run a base policy, learned dynamics and a planning baseline.</p></div><div class="phase-cell"><div class="label">02 / Weeks 5–8</div><h3>Develop the method</h3><p>Fine-tune in imagination, verify real effects, compare active versus random correction.</p></div><div class="phase-cell"><div class="label">03 / Weeks 9–12</div><h3>Demonstrate & communicate</h3><p>Run ablations, package evidence, rehearse interviews and release a reproducible artifact.</p></div></div>
    <div class="section-head"><h2>Your first week</h2><a href="week-01.html">Daily plan →</a></div><div class="grid-2"><div class="card"><div class="card-label">Weekly deliverables</div>{''.join(check(f'week-1-output-{i}',t) for i,t in enumerate(WEEKS[0]['outputs']))}</div><div class="card"><div class="card-label">Start with what you can explain</div><p>Use the self-assessment to skip familiar material through a demonstration of competence. Protect time for implementation from day one.</p><a href="theory.html#self-assessment">Run the self-assessment →</a><p class="small" style="margin-top:18px">Plan dates: <span data-plan-range></span><br>Outreach begins: <strong data-outreach-date></strong></p></div></div>
    <div class="callout green"><strong>What counts as progress:</strong> a derivation you can explain, code you can run, a result you can reproduce, or a failure you can diagnose. Reading alone is an input, not a deliverable.</div>
    <div class="section-head"><h2>Make the schedule yours</h2></div><div class="card"><div class="settings-row"><label for="planStart">Program start</label><input type="date" id="planStart" value="2026-10-14"><span class="muted">Week 7 always follows six full weeks.</span></div><p class="small muted" style="margin-top:16px">Six seven-hour core days = 42 hours/week, 504 hours total. A seventh day is recovery or optional overflow. Extra time within your 6–8 h/day availability goes to integration and reruns. The remaining calendar buffer is <span data-buffer-range></span>.</p></div>'''
    write('index.html','The Physical AI program',body,'index.html','Overview','A detailed three-month program: robot-learning foundations, coding labs and obstruction-triggered policy adaptation. Outreach begins in week 7.')

def build_roadmap():
    body=heading('01 / Weekly roadmap','Twelve weeks. Clear deliverables.','Six focused days each week. Separate time for theory, implementation, research and interview preparation; no double-counted hours.')
    body+='<div class="callout"><strong>Your outreach boundary:</strong> private preparation during weeks 1–6. Researcher conversations, applications and follow-ups begin in week 7: <strong data-outreach-date></strong>.</div>'
    body+='<div class="filter-row" aria-label="Filter weeks">'+''.join(f'<button class="filter{(" active" if t=="All" else "")}" data-filter="{t}" aria-pressed="{str(t=="All").lower()}">{t}</button>' for t in ['All','Foundations','Method','Evidence','Release'])+'</div><div class="grid-3">'+''.join(weekcard(w) for w in WEEKS)+'</div>'
    body+='<div class="section-head"><h2>The complete time ledger</h2></div><div class="table-wrap"><table><thead><tr><th>Week</th><th>Theory</th><th>Labs</th><th>Research</th><th>Interview / career</th><th>Total</th></tr></thead><tbody>'+''.join(f'<tr><td><a href="week-{w["n"]:02}.html">{w["n"]:02}</a></td>'+''.join(f'<td>{h} h</td>' for h in w['hours'])+'<td>42 h</td></tr>' for w in WEEKS)+'</tbody></table></div>'
    body+='<p class="muted small">Scope and timeboxes are adjustable at development gates. Reallocate hours when you already demonstrate mastery; use optional labs as replacements, not additional mandatory work.</p>'
    write('roadmap.html','Weekly roadmap',body,'roadmap.html')
    for w in WEEKS:
        n=w['n']; body=f'<div class="breadcrumb"><a href="roadmap.html">Weekly roadmap</a> / Week {n:02}</div>'+heading(f'Week {n:02} / {w["phase"]}',w['title'],w['aim'])
        body+=f'<div class="card"><div class="card-top"><span data-week-date="{n}" class="week-date"></span><span class="tag">42 core hours</span></div>{hours(w)}</div>'
        secs=[]
        daily='<p>Day 1 starts on your selected program date; the labels are work sessions, not fixed weekdays. Divide each session using the week’s hour ledger.</p>'
        daily+=''.join(f'<div class="day"><div class="day-index">DAY {i+1:02}</div><div><h3>{E(title)}</h3><p>{E(desc)}</p></div></div>' for i,(title,desc) in enumerate(w['days']))
        daily+='<div class="day"><div class="day-index">DAY 07</div><div><h3>Recover or absorb overflow</h3><p>Keep this day flexible. Optional reading or a delayed run can fit here; do not assume another full mandatory workday.</p></div></div>'
        secs.append(('daily','The daily plan',daily))
        study='<h3>Theory modules</h3><div class="resource-links">'+''.join(f'<a class="resource-link" href="theory-{E(m)}.html">{E(next(x["title"] for x in MODULES if x["id"]==m))}</a>' for m in w['modules'])+'</div>'
        if w['labs']: study+='<h3>Implementation assignments</h3>'+ul_links([(f'lab-{LAB_BY_ID[l]["number"]}.html',f'Lab {LAB_BY_ID[l]["number"]}: {LAB_BY_ID[l]["title"]}') for l in w['labs']])
        study+='<h3>Paper reading</h3>'+(refs(w['papers']) if w['papers'] else '<p>Prioritize writing, reruns and role-specific review. Read a new paper only to resolve a concrete question.</p>')
        study+='<p><a href="reading.html#reading-method">Use the paper-reading template</a>: extract setting, model, update, actual experiment, limitations and a reproducible question.</p>'
        secs.append(('assignments','Study and implementation',study))
        secs.append(('deliverables','The deliverables',''.join(check(f'week-{n}-output-{i}',t) for i,t in enumerate(w['outputs']))))
        secs.append(('decision','Decision gate',f'<div class="callout">{E(w["gate"])}</div><h3>Explain this without notes</h3><p>{E(w["explain"])}</p><p class="small muted">Record a short answer, identify where your reasoning is vague, and revisit only those gaps.</p>'))
        secs.append(('notes','Private review notes',f'<label class="small muted" for="weekNotes">What worked, what failed, and what changes next week?</label><textarea id="weekNotes" class="notes" data-note="week-{n}" placeholder="Record evidence, questions and next actions. Saved only in this browser."></textarea>'))
        body+=article(secs)
        body+='<div class="week-nav">'+(f'<a class="button secondary" href="week-{n-1:02}.html">← Week {n-1}</a>' if n>1 else '<a class="button secondary" href="index.html">← Overview</a>')+(f'<a class="button" href="week-{n+1:02}.html">Week {n+1} →</a>' if n<12 else '<a class="button" href="research.html#release">Release checklist →</a>')+'</div>'
        write(f'week-{n:02}.html',f'Week {n:02}: {w["title"]}',body,'roadmap.html','Week',w['aim']+' '+w['explain'])

def ul_links(items): return '<ul>'+''.join(f'<li><a href="{E(href)}">{E(label)}</a></li>' for href,label in items)+'</ul>'

def build_theory():
    body=heading('02 / Theory & foundations','Understand it well enough to use it.','Build on existing modeling and research strengths. Focus new study on robotics, RL, control, learned dynamics and rigorous experiments.')
    body+='<section id="self-assessment" class="card"><div class="card-label">Before you start / 90 minutes</div><h2>A practical self-assessment</h2><p>Score each area 0–3: <strong>0</strong> unfamiliar; <strong>1</strong> can recognize; <strong>2</strong> can explain/derive; <strong>3</strong> can implement/debug and discuss limitations. Start with the lowest-scoring core areas. Skip a module only after demonstrating its gate.</p>'+ul(['Derive a Bellman target and policy gradient, including a baseline.','Trace a PPO/SAC update with tensor dimensions and correct terminal masks.','Compose a camera-to-base transform and explain a robot action interface.','Compare BC, diffusion/flow policies, VLAs and action-conditioned world models.','Explain model-based planning versus persistent policy adaptation.','Design an evaluation with held-out layouts, a fair baseline and honest cost accounting.'])+'<label class="small muted" for="assessmentNotes">Your starting point</label><textarea class="notes" id="assessmentNotes" data-note="assessment" placeholder="Scores, strengths you can skip through, and priority gaps."></textarea></section>'
    body+='<div class="section-head"><h2>The core knowledge map</h2></div><div class="grid-3">'
    for i,m in enumerate(MODULES):
        body+=f'<div class="card"><div class="card-top"><span class="card-number">{i+1:02}</span><span class="tag">Weeks {E(m["weeks"])}</span></div><h3><a href="theory-{m["id"]}.html">{E(m["title"])}</a></h3><p>{E(m["question"])}</p><div class="card-footer"><span>{E(m["hours"])} h · {E(m["level"])}</span><a href="theory-{m["id"]}.html">Study →</a></div></div>'
    body+='</div><div class="callout green"><strong>Depth rule:</strong> each module ends in a derivation, an implementation or inspection, an explanation and a concrete mastery check. The goal is transfer into your experiment and your interview answers.</div>'
    write('theory.html','Theory and foundations',body,'theory.html')
    for m in MODULES:
        lab=LAB_BY_ID[m['lab']]
        body='<div class="breadcrumb"><a href="theory.html">Theory & foundations</a> / '+E(m['title'])+'</div>'+heading('Core knowledge / Weeks '+m['weeks'],m['title'],m['question'])
        body+=f'<div class="tags"><span class="tag">{E(m["level"])}</span><span class="tag">{E(m["hours"])} study hours</span><a class="tag" href="lab-{lab["number"]}.html">Connected lab {lab["number"]} →</a></div>'
        secs=[('concepts','What to understand',ul(m['topics'])),('derive','What to derive or explain',ol(m['derive'])),('implement','Connect it to code',f'<p>{E(m["implement"])}</p><a class="button secondary" href="lab-{lab["number"]}.html">Open the implementation brief →</a>'),('resources','Primary resources',refs(m['resources'])+'<p class="small muted">Use author documentation and repositories. Record the exact revision for any code you run. Links were reviewed for this plan; runtime compatibility must be checked in your environment.</p>'),('interview','Interview retrieval practice',ul(m['interview'])),('gate','Mastery check',f'<div class="callout">{E(m["gate"])}</div>'+check('module-'+m['id'],'I can demonstrate this mastery check without following a tutorial.'))]
        body+=article(secs)
        write(f'theory-{m["id"]}.html',m['title'],body,'theory.html','Theory',m['question']+' '+' '.join(m['topics']))

def build_labs():
    body=heading('03 / Implementation labs','Turn concepts into working code.','Twelve bounded assignments. Implement the essential mechanics yourself; reproduce and modify larger systems instead of rebuilding every framework.')
    body+='<div class="callout"><strong>Spinning Up belongs here.</strong> Use it for conceptual explanations and update equations. Treat its original code as a reference with older dependencies. Use an isolated environment and current documented examples from CleanRL, Gymnasium or Stable-Baselines3 for runnable baselines.</div><p class="small muted">Lab estimates fit inside the weekly ledger. Research-integrated labs use the research allocation as well as coding time; they are not extra hours added on top of the schedule.</p>'
    body+='<div class="grid-3">'
    for l in LABS:
        body+=f'<div class="card"><div class="card-top"><span class="card-number">LAB {l["number"]}</span><span class="tag">{l["hours"]} h</span></div><h3><a href="lab-{l["number"]}.html">{E(l["title"])}</a></h3><p>{E(l["brief"])}</p><div class="card-footer"><span>Week {E(l["week"])} · {E(l["mode"])}</span><a href="lab-{l["number"]}.html">Build →</a></div></div>'
    body+='</div><div class="section-head"><h2>What is included now?</h2></div><div class="card"><p>The website ships with five original, runnable teaching examples: a Bellman gridworld, kinematics checks, a PPO update, a CEM planner, and evaluation/acquisition utilities. The larger assignments are detailed implementation briefs; they are not presented as finished robot-research code.</p><a href="examples/README.md">Open the starter-code guide →</a></div>'
    write('implementation.html','Implementation labs',body,'implementation.html')
    for l in LABS:
        body='<div class="breadcrumb"><a href="implementation.html">Implementation labs</a> / Lab '+l['number']+'</div>'+heading('Lab '+l['number']+' / Week '+l['week'],l['title'],l['brief'])
        body+=f'<div class="tags"><span class="tag">{l["hours"]} focused hours</span><span class="tag">{E(l["mode"])}</span><a class="tag" href="theory-{l["module"]}.html">Theory companion →</a></div>'
        if l['file']: body+=f'<a class="code-link" href="examples/{l["file"]}" download><span>↓ Starter: {E(l["file"])}</span><span>Python</span></a>'
        starter=(f'<pre><code>python3 examples/{E(l["file"])}</code></pre><p>The example prints its own teaching checks. Read <a href="examples/README.md">dependencies and limitations</a> first. A passing teaching example is not a completed research experiment.</p>' if l['file'] else '<p>This lab is an implementation brief, not a claim that the complete system is supplied. Create the smallest reproducible version in your experiment repository, using the linked source as a reference.</p>')
        secs=[('build','The implementation sequence',ol(l['steps'])),('check','How to verify it',ul(l['checks'])),('deliver','What to produce',f'<div class="callout green">{E(l["output"])}</div>'),('starter','Start here',starter+refs(l['resources'])),('scope','Timebox and optional depth',f'<p>{E(l["stretch"])}</p><p>When the timebox is exhausted, preserve a minimal working result and record unresolved questions. Optional work replaces another optional item; it does not expand the 42-hour week.</p>'+check('lab-'+l['id'],'I have a runnable artifact and can explain its verification and limitations.'))]
        body+=article(secs)
        write(f'lab-{l["number"]}.html',f'Lab {l["number"]}: {l["title"]}',body,'implementation.html','Lab',l['brief']+' '+' '.join(l['steps']))

def build_research():
    body=heading('04 / Research project','Obstruction-triggered self-improvement.','A proposed study of imagined policy adaptation, real-world verification and active correction. One task first; claims follow evidence.')
    body+='<div class="tags"><span class="tag">Proposed protocol</span><span class="tag">One arm · one core task</span><span class="tag">Learned predictive model</span><span class="tag orange">No results implied</span></div>'
    sections=list(PROJECT_SECTIONS)
    release_items=['Core code/configurations run from a clean setup.','Data/split manifests and paired imagined/executed examples are documented.','Metrics, uncertainty, costs and failed trials are reported.','A two-minute demo and technical presentation match real checkpoints.','The report states assumptions, related-work overlap and limitations.','Authorship, licenses and release permissions are resolved.']
    sections[-1]=(sections[-1][0],sections[-1][1],sections[-1][2]+''.join(check(f'release-{i}',t) for i,t in enumerate(release_items)))
    body+=article(sections)
    write('research.html','Research project and experiment protocol',body,'research.html','Research','Detailed experiment design: task, architecture, imagined policy updates, active physical verification, baselines, budgets, data splits, metrics and decision gates.')

def build_reading():
    body=heading('05 / Reading room','Read for mechanisms and evidence.','A prioritized reading map. Neural world models, structured skill-effect models, symbolic planning and physics-based systems are labeled separately.')
    body+='<section id="reading-method" class="card"><div class="card-label">A repeatable 60–90 minute pass</div><h2>The six-question paper note</h2>'+ol(['Setting: what is known, what changes, and what data/interaction are allowed?','Model: what is learned, predicted or supplied by a simulator?','Update: which parameters change, and is adaptation at training time or deployment?','Evidence: which exact experiment demonstrates the behavior? Locate the figure, section and hardware/simulation distinction.','Comparison: which baseline, budget, split and sample count support the claim?','Transfer: what can we reproduce or reuse, and what limitation matters for our project?'])+'<p>Read two papers deeply per week early in the program; scan additional titles only to answer a specific gap. By Weeks 9–12, prioritize writing and evidence over an expanding reading backlog.</p></section>'
    body+='<div class="section-head"><h2>The project reading sequence</h2></div><div class="grid-2">'
    for key,when,kind,question,limit in PAPERS:
        title,url=RESOURCES[key]
        body+=f'<div class="card"><div class="card-top"><span class="tag">{E(when)}</span><span class="card-number">↗</span></div><div class="card-label">{E(kind)}</div><h3><a href="{E(url)}" target="_blank" rel="noopener">{E(title)}</a></h3><p><strong>Read to answer:</strong> {E(question)}</p><p><strong>Evidence boundary:</strong> {E(limit)}</p></div>'
    body+='</div><section id="novelty" class="card" style="margin-top:24px"><h2>Keep a living novelty matrix</h2><p>For each close paper, track learned model type, policy-update timing, obstruction novelty, model correction, real-trial selection, real-data budget, planning baseline and hardware evidence. The absence of a feature in an abstract does not establish novelty. Recheck the literature in Weeks 6 and 9 and before submission.</p><p>Promising comparison: event-triggered policy adaptation with actively selected physical correction. This remains a research hypothesis until the closest methods and their appendices have been checked.</p></section>'
    write('reading.html','Reading room and related-work boundaries',body,'reading.html','Reading','Paper-reading questions, evidence boundaries, world-model classifications and a novelty matrix for obstruction-triggered adaptation.')

def build_interviews():
    body=heading('06 / Interview preparation','Be able to explain the whole system.','Prepare from day one; begin outreach only after six full weeks. Combine fundamentals, coding, research judgment and evidence from your own implementation.')
    body+='<div class="callout"><strong>Outreach starts in Week 7:</strong> <span data-outreach-date></span>. Weeks 1–6 are private study, coding, project work and rehearsal. This website does not send messages or create scheduled outreach.</div>'
    body+='<section id="career"><h2>The career preparation sequence</h2><div class="grid-2">'+''.join(f'<div class="card"><div class="card-label">{E(period)}</div><h3>{E(title)}</h3><p>{E(desc)}</p></div>' for period,title,desc in CAREER_PHASES)+'</div></section>'
    body+='<section id="coding" style="margin-top:36px"><h2>Coding practice that supports the role</h2>'+''.join(f'<details><summary>{E(title)}</summary><div class="answer">{E(desc)}</div></details>' for title,desc in CODING_PRACTICE)+'</section>'
    body+='<section id="questions" style="margin-top:36px"><h2>Thirty questions to answer with evidence</h2><p class="muted">Answer aloud before expanding the rubric. Use equations, dimensions, one concrete example and one limitation.</p><div class="filter-row">'+''.join(f'<button class="filter{(" active" if t=="All" else "")}" data-filter="{t}" aria-pressed="{str(t=="All").lower()}">{t}</button>' for t in ['All','RL','Robotics','Policies','World models','Research','Systems','Career'])+'</div>'
    body+=''.join(f'<details data-category="{E(category)}"><summary><span class="card-number">{i+1:02} / {E(category)}</span><br>{E(question)}</summary><div class="answer"><strong>A strong answer should cover:</strong> {E(answer)}</div></details>' for i,(category,question,answer) in enumerate(QUESTIONS))+'</section>'
    body+='<section id="narrative" class="card" style="margin-top:30px"><h2>Your project, at three depths</h2>'+ul(['2 minutes: physical problem, why a learned model helps, your method, one measured result and one limitation.','10 minutes: setting, strongest related work, architecture, baseline fairness, main figures and failure analysis.','30 minutes: equations, tensor/data flow, implementation decisions, ablations, statistical uncertainty, costs and next research steps.'])+'<p>Prepare three prior-research stories as well: a technical contribution, a difficult failure/debugging episode, and leadership/collaboration. Connect existing expertise to the new robot-learning evidence without implying that three months covers every robotics specialty.</p></section>'
    write('interviews.html','Interview and career preparation',body,'interviews.html','Interview','Thirty interview questions, coding practice, project presentation rubrics and an outreach schedule beginning in week 7.')

def build_resources():
    body=heading('07 / Resource library','A small stack, used deliberately.','Read the theory references deeply and pin the code you actually run. Repository availability is not a guarantee of checkpoint, GPU or robot-interface compatibility.')
    groups=[('Explain and derive',['spinning','pg','sac','modern','underactuated']),('Run baseline algorithms',['cleanrl','sb3','gym','mujoco']),('Collect data and learn policies',['lerobot','minari','robomimic','diffusion','openpi']),('Learn and plan with world models',['dreamer','dinowm','tdmpc','dreamzero']),('Read the closest research',['daydreamer','fosp','rise','reoi','fail2progress','resync','replan'])]
    for title,keys in groups:
        body+=f'<section style="margin-bottom:30px"><h2>{E(title)}</h2><div class="grid-2">'+''.join(f'<div class="card"><h3><a href="{E(RESOURCES[k][1])}" target="_blank" rel="noopener">{E(RESOURCES[k][0])} ↗</a></h3><p class="mono" style="overflow-wrap:anywhere">{E(RESOURCES[k][1])}</p></div>' for k in keys)+'</div></section>'
    body+='<section class="card"><h2>Environment and provenance rules</h2>'+ol(['Keep the learning sandbox and research training environments separate. Do not force older Spinning Up dependencies into the main robot stack.','Use repository setup instructions for your platform. Pin the working commit and resolved dependencies after the first successful run.','Use local CPU/MPS for small exercises; measure GPU requirements before selecting a large predictor or policy.','Keep raw robot logs and large checkpoints out of the website repository. Publish only the approved artifact and documented samples.','Record code revision, seed, config, split manifest, model/data source and actual device in every run.'])+'<p>Resource review date: October 14, 2026. The curriculum contains original assignments; source links support further study and implementation. Paper claims and compatibility should be rechecked before reproductions or publication.</p></section>'
    write('resources.html','Resource library and implementation references',body,'resources.html')

if __name__ == '__main__':
    assert len({x for x in CHECKS}) == len(CHECKS)
    assert all(sum(w['hours']) == 42 and len(w['days']) == 6 for w in WEEKS)
    build_overview();build_roadmap();build_theory();build_labs();build_research();build_reading();build_interviews();build_resources()
    (ROOT/'assets/search-index.js').write_text('window.PLAN_CHECKS='+json.dumps(CHECKS)+';\nwindow.PLAN_SEARCH='+json.dumps(SEARCH,ensure_ascii=False)+';\n',encoding='utf-8')
    (ROOT/'plan.json').write_text(json.dumps(dict(start='2026-10-14',weeks=WEEKS,modules=MODULES,labs=LABS,resources=RESOURCES,outreach_week=7,weekly_hours=42),ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'Built {len(SEARCH)} pages, {len(CHECKS)} progress checks, {sum(sum(w["hours"]) for w in WEEKS)} core hours.')
